 // distant city silhouette
 for(let i=0;i<18;i++){const x=((i*173+frame*.12)% (W+160))-80,hh=rand(35,115);ctx.fillStyle=i%2?'#253638':'#304342';ctx.fillRect(x,horizon-hh,rand(32,90),hh+10)}
 // road vanishing perspective
 const roadTop=W*.11,roadBottom=W*.86;ctx.fillStyle='#303c3a';ctx.beginPath();ctx.moveTo(W/2-roadTop*.5,horizon);ctx.lineTo(W/2+roadTop*.5,horizon);ctx.lineTo(W/2+roadBottom*.5,H);ctx.lineTo(W/2-roadBottom*.5,H);ctx.closePath();ctx.fill();
