 const project=(x,y)=>{const dx=x-px,dy=y-py,depth=dx*fx+dy*fy,side=dx*sx+dy*sy;if(depth<8)return null;const focal=Math.min(W,H)*.8,scale=focal/depth;return {x:W/2+side*scale,y:horizon+focal*1.1/depth,scale,depth}};
