 else if(o.type==='bush'){const r=clamp(p.scale*13,2,70);ctx.fillStyle='#355a43';ctx.beginPath();ctx.ellipse(p.x,p.y-r*.4,r*1.2,r*.65,0,0,Math.PI*2);ctx.fill();}
 else if(o.type==='enemy'){const s=clamp(p.scale*13,3,44);ctx.fillStyle='#ff5a52';ctx.fillRect(p.x-s/2,p.y-s,s,s*.45);ctx.fillStyle='#e7e4c9';ctx.beginPath();ctx.arc(p.x,p.y-s/2,s*.32,0,Math.PI*2);ctx.fill();}
